// src/contexts/ShipperLocationContext.js
// ---------------------------------------------
import React, {
  createContext,
  useContext,
  useState,
  useEffect,
  useCallback,
} from "react";
import axios from "axios";
import { useAuth } from "../AuthContext";
import Toast from "../../components/common/Toast";
import { SHIPPER_API_BASE_URL as API_BASE_URL } from "../../config/api";

const ShipperLocationContext = createContext();
export const ShipperLocationProvider = ({ children }) => {
  const { token, user } = useAuth();

  const [location, setLocation] = useState(null);
  const [loading, setLoading] = useState(false);

  // ---------------- TOAST HANDLER ----------------
  const showToast = useCallback((message, type = "info") => {
    if (Toast[type]) {
      Toast[type](message);
    } else {
      Toast.info(message);
    }
  }, []);

  // ---------------- FETCH CURRENT LOCATION (Silent) ----------------
  const fetchCurrentLocation = useCallback(async () => {
    if (!token) return;

    try {
      const res = await axios.get(`${API_BASE_URL}/current-location`, {
        headers: { Authorization: `Bearer ${token}` },
      });

      setLocation(res?.data?.data || null);
    } catch (err) {
      console.error(
        "Fetch Location Error:",
        err?.response?.data || err.message
      );
      // silent (no toast)
    }
  }, [token]);

  // ---------------- UPDATE CURRENT LOCATION ----------------
  const updateLocation = async (locationData) => {
    if (!token) return { success: false };

    setLoading(true);
    try {
      const res = await axios.put(
        `${API_BASE_URL}/update-location`,
        locationData,
        {
          headers: { Authorization: `Bearer ${token}` },
        }
      );

      setLocation(res?.data?.data || locationData);

      // showToast("Location updated successfully", "success");

      return { success: true };
    } catch (err) {
      console.error(
        "Update Location Error:",
        err?.response?.data || err.message
      );

      showToast(
        err?.response?.data?.message || "Failed to update location",
        "error"
      );

      return { success: false };
    } finally {
      setLoading(false);
    }
  };

  // ---------------- AUTO FETCH ON LOGIN ----------------
  useEffect(() => {
    if (token && user?.role === "shipper") {
      fetchCurrentLocation();
    } else {
      setLocation(null);
    }
  }, [token, user, fetchCurrentLocation]);

  // ---------------- CONTEXT PROVIDER ----------------
  return (
    <ShipperLocationContext.Provider
      value={{
        location,
        loading,
        fetchCurrentLocation,
        updateLocation,
      }}
    >
      {children}
    </ShipperLocationContext.Provider>
  );
};

export const useShipperLocation = () => useContext(ShipperLocationContext);
